'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const themes={mint:{name:'차콜 민트',colors:['#121212','#1e1e1e','#333333','#e8e8e8','#b8b8b8','#8fd0b8','#00382b','#244b3d','#9a9a9a']},paper:{name:'페이퍼 블루',colors:['#f6f7fa','#ffffff','#e2e7ee','#172231','#505c6c','#2056a0','#ffffff','#d9e7ff','#647184']},blue:{name:'미드나이트 블루',colors:['#101824','#1c2939','#293b50','#eff4fc','#b4c4d8','#a4caff','#102d51','#253f60','#94a7bf']},amber:{name:'웜 앰버',colors:['#1c1713','#2b231d','#40332a','#f4ede6','#cdbcaf','#efbe7a','#39230a','#513b21','#ad9988']}};
const screens={camera:['camera','01 / CAMERA','카메라','연결하고, 고르고, 가져오기.'],photos:['photos','02 / LIBRARY','사진','선택한 사진과 다음 작업을 가까이.'],detail:['photos','03 / PHOTO','사진 상세','원본을 확인하고 편집을 시작하세요.'],editor:['tune','04 / EDITOR','사진 편집','사진은 크게, 조정은 가까이. 저장은 언제나 같은 자리에.'],recipes:['recipes','05 / RECIPES','레시피','마음에 든 색을 사진과 함께 보관하세요.'],settings:['settings','06 / SETTINGS','설정','내 취향에 맞게, 읽기 편하게.']};
const luts=[['Original','원본','#959fa3'],['PORTRA 400','네거','#dcae56'],['GOLD 200','네거','#e8b327'],['VELVIA 50','슬라이드','#4d9473'],['HP5 PLUS','흑백','#a9a8a2'],['PRINT 2383','시네마','#80aab4']];
function stored(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
const photos=Array.from({length:9},(_,i)=>({id:'demo'+i,url:'assets/'+['street','cafe','forest'][i%3]+'.jpg',name:'DSC'+String(1024+i).padStart(5,'0')+'.JPG',external:i===4,edited:i===1||i===5,raw:i===7}));
const defaults={exposure:0,contrast:0,saturation:0,strength:75,distortion:0,lut:1};
const state={screen:'editor',layout:innerWidth<760?'phone':'wide',theme:stored('b7c-theme','mint'),mode:'current',photoId:'demo0',filter:'전체',selection:false,selected:new Set(),tab:'기본',category:'네거',edit:{...defaults},undo:[],redo:[],compare:false,connected:false,recipes:stored('b7c-recipes',[{id:'warm',name:'서울의 오후',photo:'demo0',edit:{...defaults}},{id:'green',name:'숲의 온도',photo:'demo2',edit:{...defaults,lut:3}}])};
if(!themes[state.theme])state.theme='mint';let icons={},credits=[],drawToken=0,toastTimer;const images=new Map();
const icon=n=>icons[n]||icons.tune||'';
const button=(label,action,cls='')=>`<button class="app-button ${cls}" data-action="${action}">${label}</button>`;
const photo=()=>photos.find(p=>p.id===state.photoId)||photos[0];
const noteTexts={camera:['MTP 가져오기와 PC Remote 실험은 서로 다른 흐름입니다.','USB 연결·새 사진 수는 웹 데모 상태입니다.'],photos:['가로 배치: 사진 목록과 우측 미리보기의 2열 구조.','선택 수·공유·레시피 적용은 하단 고정 영역에 모았습니다.'],detail:['사진 자체를 넓게 보여주고 편집 진입을 고정합니다.','웹에서 추가한 사진은 서버로 전송하지 않습니다.'],editor:['미리보기 · 스크롤 조정 영역 · 고정 저장 버튼을 분리했습니다.','왜곡은 전체 사진의 수동 조절입니다. .cube LUT에는 포함하지 않습니다.','웹의 색 표현은 CSS 근사치이며 실제 앱 LUT 결과와 다릅니다.'],recipes:['커버 사진 좌상단에 사용 LUT 배지를 표시합니다.','웹에 저장한 레시피는 이 브라우저에서만 유지됩니다.'],settings:['4가지 테마는 실제 앱 색상값을 사용했습니다.','테마 선택은 브라우저를 다시 열어도 유지됩니다.']};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function modal(title,body,actions=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="modal-heading"><h2>${title}</h2><button class="quiet" data-action="close" aria-label="닫기">✕</button></div>${body}<div class="modal-actions">${actions||'<button class="studio-button" data-action="close">확인</button>'}</div>`;if(!d.open)d.showModal()}
function navigate(s){state.screen=s;state.compare=false;render()}
function theme(t){state.theme=t;persist('b7c-theme',t);render()}
function fit(){const sizes={phone:[390,760],portrait:[620,800],wide:[940,600]},[w,h]=sizes[state.layout],stage=$('.stage'),scale=Math.min(1,(stage.clientWidth-32)/w);const d=$('#device');d.style.width=w+'px';d.style.height=h+'px';d.style.transform=`scale(${scale})`;$('#device-holder').style.width=w*scale+'px';$('#device-holder').style.height=h*scale+'px';$('#viewport-label').textContent=`${w} × ${h} · ${Math.round(scale*100)}%`}
function appNav(){return ['camera','photos','recipes','settings'].map(s=>`<button class="app-nav-button ${state.screen===s?'active':''}" data-screen="${s}">${icon(screens[s][0])}<span>${screens[s][2]}</span></button>`).join('')}
function heading(t,sub='',action=''){return `<header class="app-heading"><div><h3>${t}</h3>${sub?`<p>${sub}</p>`:''}</div>${action}</header>`}
function thumb(p){return `<button class="photo-card ${state.selected.has(p.id)?'selected':''}" data-photo="${p.id}" aria-label="${esc(p.name)}${state.selection?' 선택':''}"><img src="${p.url}" alt="데모 사진 ${esc(p.name)}" loading="lazy" style="object-position:${p.id==='demo3'?'25%':'50%'} center"><span class="photo-name">${esc(p.name)}</span>${p.external?'<span class="photo-badge">외부</span>':p.edited?'<span class="photo-badge">편집됨</span>':p.raw?'<span class="photo-badge">RAW</span>':''}${state.selection?`<span class="select-check">${state.selected.has(p.id)?'✓':''}</span>`:''}</button>`}
function photoActions(){return `<div class="fixed-actions">${button('레시피 적용','edit')}</div>`}
function photosView(){const filtered=photos.filter(p=>state.filter==='전체'||state.filter==='외부'&&p.external||state.filter==='편집됨'&&p.edited||state.filter==='미편집'&&!p.edited||state.filter==='RAW'&&p.raw);const h=heading(`사진 <small>· ${photos.length}장</small>`,'',button('사진 추가','import','small outline')+button(state.selection?'선택 종료':'선택','select','small text'));const filters=`<div class="chip-strip">${['전체','미편집','편집됨','RAW','외부'].map(f=>`<button class="chip ${state.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>`;const grid=`<div class="app-scroll"><div class="photo-grid">${filtered.map(thumb).join('')||'<p class="app-empty">해당 사진이 없습니다.</p>'}</div></div>`;const sel=`<div class="selection-footer"><span class="selection-count">${state.selected.size}장 선택</span>${button('공유','share-selection','outline small')}${button('레시피 적용','apply-selection','small')}</div>`;if(state.layout==='wide'&&!state.selection)return `<div class="photo-landscape"><section class="list-pane">${h}${filters}${grid}</section><section class="detail-pane"><div class="photo-large"><img src="${photo().url}" alt="선택한 사진"></div><div class="photo-info"><h4>${esc(photo().name)}</h4><p>원본은 수정되지 않습니다.</p>${button('상세 보기','detail','text small')}</div>${photoActions()}</section></div>`;return h+filters+grid+(state.selection?sel:'')}
function detailView(){return heading('사진 상세','',button(icon('back')+' 목록','photos','text small'))+`<div class="photo-detail"><div class="photo-large"><img src="${photo().url}" alt="선택한 사진"></div><div class="detail-information"><div class="photo-info"><h4>${esc(photo().name)}</h4><p>${photo().external?'외부 이미지 · 브라우저에서 추가':'α7C JPEG · 예시 메타데이터'}</p><p>원본은 수정되지 않습니다.</p><p>웹 시안용 이미지</p></div>${photoActions()}${button(icon('share')+' 공유','share-photo','outline')}</div></div>`}
function range(name,key,min=-100,max=100){return `<div class="control-row"><label for="range-${key}">${name}</label><output id="value-${key}">${state.edit[key]}</output><button class="icon-button" data-reset="${key}" aria-label="${name} 초기화">${icon('reset')}</button></div><input class="range-control" id="range-${key}" type="range" min="${min}" max="${max}" value="${state.edit[key]}" data-range="${key}">`}
function adjustment(){if(state.tab==='왜곡')return `<h4 class="section-label">사진 전체 왜곡</h4>${range('배럴 ↔ 핀쿠션','distortion')}<div class="range-ends"><span>배럴</span><span>0</span><span>핀쿠션</span></div><p class="app-hint">사진 전체를 변형하며 가장자리가 일부 잘립니다. 렌즈 자동 보정이 아닙니다.</p><p class="app-hint">레시피·일괄 적용에 포함 · .cube LUT에는 제외</p>`;if(state.tab==='톤커브')return `<h4 class="section-label">톤커브</h4><div class="curve-chart"><svg viewBox="0 0 240 150" aria-label="톤커브 구조 예시"><path d="M0 150C70 135 150 20 240 0" fill="none" stroke="var(--accent)" stroke-width="3"/></svg></div><p class="app-hint">곡선은 화면 구조 예시입니다. 웹 조절은 기본·왜곡 탭에서 체험하세요.</p>`;if(state.tab==='HSL')return '<h4 class="section-label">색상별 조정</h4><div class="hsl-colors">'+['#ef7373','#ec9b50','#e5cd61','#82b485','#6ab6bd','#7498d1','#ab89cf','#d58cae'].map(c=>`<span style="background:${c}"></span>`).join('')+'</div><p class="app-hint">HSL 선택 영역의 구성 예시입니다.</p>';if(state.tab==='효과')return '<h4 class="section-label">필름의 질감</h4><p class="app-hint">앱의 그레인·비네팅·할레이션 조정 영역입니다. 웹에서는 화면 구조를 보여줍니다.</p>';return range('노출','exposure')+range('대비','contrast')+range('채도','saturation')}
function editorView(){const tiles=luts.map((l,i)=>`<button class="lut-tile ${state.edit.lut===i?'active':''}" data-lut="${i}"><span class="film-canister" style="--film:${l[2]}"><span class="film-label">${i?l[0].split(' ')[0]:'β7C'}</span></span><span>${l[0]}</span></button>`).join('');return `<div class="editor"><div class="editor-body"><section class="preview-column">${heading('사진 편집',esc(photo().name),button(icon('back'),'photos','text small'))}<div class="editor-visual"><canvas id="photo-canvas" aria-label="편집 사진 미리보기"></canvas><span class="visual-tag">${state.compare?'원본 비교':'WEB PREVIEW'}</span></div></section><section class="editor-controls"><h4 class="section-label">LUT</h4><div class="chip-strip">${['보관','네거','슬라이드','시네마','흑백','크리에이티브','사용자'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="lut-row">${tiles}</div>${range('강도','strength',0,100)}<h4 class="section-label">세부 조정</h4><div class="edit-tabs">${['기본','톤커브','HSL','효과','왜곡'].map(t=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${t}</button>`).join('')}</div>${adjustment()}${state.mode==='concept'?'<details class="mock-summary"><summary>조정 범위 안내</summary><p class="app-hint">색 조절과 기하 보정을 구분해 설명하는 개선 제안입니다. 앱에는 미적용 상태입니다.</p></details>':''}</section></div><footer class="editor-footer"><div class="compare-group"><button class="icon-button ${state.compare?'active':''}" data-action="compare" aria-label="원본 비교" title="원본 비교">${icon('compare')}</button><button class="icon-button" data-action="undo" aria-label="실행 취소" ${state.undo.length?'':'disabled'}>${icon('undo')}</button><button class="icon-button" data-action="redo" aria-label="다시 실행" ${state.redo.length?'':'disabled'}>${icon('redo')}</button></div>${button('레시피 저장','recipe-save','outline')}${button('사진 저장','photo-save')}</footer></div>`}
function cameraView(){return heading('Sony 카메라',state.mode==='concept'?'연결 → 사진 선택 → 가져오기':'USB 가져오기')+`<div class="app-scroll camera-columns"><section class="app-card"><span class="connection-chip">${state.connected?'● 데모 연결됨':'○ 연결 대기'}</span><h3>α7C <small>ILCE-7C</small></h3><p class="app-hint">${state.connected?'USB 연결 상태를 모의한 화면입니다.':'카메라 전원을 켜고 USB-C 케이블로 연결하세요. USB 연결 모드는 MTP로 설정합니다.'}</p>${state.connected?'<div class="big-count">3 <small>장의 새 사진</small></div>'+button('새 사진 가져오기','camera-import')+button('골라서 가져오기','photos','outline')+button(icon('refresh')+' 다시 스캔','scan','text'):button('데모 연결하기','connect')+button('USB 설정 안내','usb-help','text')}</section><section class="app-card outlined"><h4>카메라와 함께</h4><p class="app-hint">썸네일 캐시로 다음 연결에서도 빠른 탐색을 돕습니다.</p><p class="status-note">라이브뷰 · BLE 위치 연동 준비 중</p>${state.mode==='concept'?'<details class="mock-summary"><summary>연구·실험 기능</summary>':''}<button class="research-link" data-action="diagnostic">PC Remote 실험 진단 ↗</button><button class="research-link" data-action="capture">AF · 단발 촬영 실험 ↗</button><p class="app-hint">실기 검증 대기 · 웹에서는 실행하지 않습니다.</p>${state.mode==='concept'?'</details>':''}</section></div>`}
function recipesView(){return heading('레시피',`${state.recipes.length}개의 색 기록`,button('코드로 가져오기','recipe-import','text small'))+`<div class="app-scroll"><div class="recipe-list">${state.recipes.map(r=>{const p=photos.find(p=>p.id===r.photo)||photos[0],l=luts[r.edit.lut]||luts[0];return `<button class="recipe-card" data-recipe="${esc(r.id)}"><div class="recipe-cover"><img src="${p.url}" alt="${esc(r.name)} 커버"><span class="lut-badge" style="border-color:${l[2]}">${esc(l[0])}</span>${r.favorite?'<span class="recipe-favorite">★</span>':''}</div><div><h4>${esc(r.name)}</h4><p>${esc(l[0])} · 왜곡 ${r.edit.distortion||0}</p></div></button>`}).join('')}</div><p class="app-hint">사진 좌상단에 사용한 LUT를 표시합니다. 이 웹에서 만든 레시피는 브라우저에만 저장됩니다.</p></div>`}
function settingsView(){return heading('설정','β7C · 0.8.8 화면 구성')+`<div class="app-scroll settings-content"><h4 class="section-label">앱 테마</h4>${Object.entries(themes).map(([id,t])=>`<button class="setting-row" data-theme="${id}"><span><strong>${t.name}</strong><small>${id==='paper'?'밝은 배경':'어두운 배경'} · 실제 앱 색상</small></span><span class="radio-dot ${id===state.theme?'selected':''}"></span></button>`).join('')}<h4 class="section-label">가져오기 · 레시피</h4><button class="setting-row" data-action="import"><span>폰 사진·외부 이미지 추가<small>브라우저에서만 처리 · 서버 업로드 없음</small></span><span>↗</span></button><button class="setting-row" data-screen="recipes"><span>레시피 관리<small>저장한 색과 왜곡 설정</small></span><span>→</span></button><div class="setting-row"><span>위치 연동<small>준비 중</small></span><span>—</span></div><h4 class="section-label">연구 · 진단</h4><button class="setting-row" data-action="diagnostic"><span>PC Remote 실험 진단<small>읽기 전용 조사와 실험 기능 분리</small></span><span>↗</span></button><button class="setting-row" data-action="logs"><span>진단 로그 공유<small>웹 데모 로그만 생성</small></span>${icon('share')}</button><button class="setting-row" data-action="about"><span>앱과 웹 시안 정보<small>0.8.8 · 현재 구현과 개선 제안</small></span><span>↗</span></button></div>`}
function render(){const s=screens[state.screen];$('#screen-kicker').textContent=s[1];$('#screen-title').textContent=s[2];$('#screen-desc').textContent=s[3];$('#screen-nav').innerHTML=Object.entries(screens).map(([k,v])=>`<button class="screen-link ${state.screen===k?'active':''}" data-screen="${k}">${icon(v[0])}<span>${v[2]}</span><small>${v[1].slice(0,2)}</small></button>`).join('');$('#theme-options').innerHTML=Object.entries(themes).map(([id,t])=>`<button class="theme-choice ${state.theme===id?'active':''}" data-theme="${id}" aria-pressed="${state.theme===id}"><span class="theme-swatch" style="background:${t.colors[0]};color:${t.colors[5]}">Aa</span><span>${t.name}</span><span class="theme-check">${state.theme===id?'✓':''}</span></button>`).join('');$('#screen-notes').innerHTML=`<span class="eyebrow">SCREEN NOTES</span><h4>${state.mode==='current'?'현재 구현 · 소스 기준':'개선 제안 · 앱 미적용'}</h4>${noteTexts[state.screen].map(t=>`<p>${t}</p>`).join('')}${state.mode==='concept'?'<p>제안: 사진 추가 동선을 강조하고 연구 기능의 보조 안내를 접어 주 작업에 집중합니다. 핵심 버튼 위치와 앱 배경은 유지합니다.</p>':''}`;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===state.mode));document.querySelectorAll('[data-layout]').forEach(b=>b.classList.toggle('active',b.dataset.layout===state.layout));const d=$('#device');d.dataset.layout=state.layout;d.classList.toggle('concept',state.mode==='concept');['bg','panel','high','text','muted','accent','onaccent','container','outline'].forEach((v,i)=>d.style.setProperty('--'+v,themes[state.theme].colors[i]));d.style.colorScheme=state.theme==='paper'?'light':'dark';const detail=['editor','detail'].includes(state.screen);$('#app-root').innerHTML=`<div class="app-layout">${!detail&&state.layout!=='phone'?`<nav class="app-rail" aria-label="앱 메뉴">${appNav()}</nav>`:''}<div class="app-page">${({photos:photosView,detail:detailView,editor:editorView,camera:cameraView,recipes:recipesView,settings:settingsView})[state.screen]()}</div>${!detail&&state.layout==='phone'?`<nav class="app-bottom-nav" aria-label="앱 메뉴">${appNav()}</nav>`:''}</div>`;fit();if(state.screen==='editor')draw()}
function imageFor(url){if(!images.has(url))images.set(url,new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=url}));return images.get(url)}
function colorFilter(){const e=state.edit,a=e.strength/100,base=e.lut===4?`grayscale(${a})`:e.lut===1?`sepia(${.2*a})`:e.lut===2?`sepia(${.33*a})`:e.lut===3?`saturate(${1+.27*a})`:'none';return `${base} brightness(${2**(e.exposure/100)}) contrast(${1+e.contrast/150}) saturate(${1+e.saturation/100})`}
async function draw(){const token=++drawToken,canvas=$('#photo-canvas');if(!canvas)return;try{const im=await imageFor(photo().url);if(token!==drawToken||!canvas.isConnected)return;const scale=Math.min(1,960/Math.max(im.width,im.height)),w=Math.round(im.width*scale),h=Math.round(im.height*scale);canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0,w,h);if(!state.compare&&state.edit.distortion){const source=ctx.getImageData(0,0,w,h),out=ctx.createImageData(w,h),cx=(w-1)/2,cy=(h-1)/2,r2=cx*cx+cy*cy,k=-.18*state.edit.distortion/100;let s=1;if(k>0){let lo=0,hi=1;for(let i=0;i<48;i++){const mid=(lo+hi)/2;if(mid+k*mid**3>1)hi=mid;else lo=mid}s=(lo+hi)/2}for(let y=0;y<h;y++)for(let x=0;x<w;x++){const dx=(x-cx)*s,dy=(y-cy)*s,f=1+k*(dx*dx+dy*dy)/r2,sx=Math.max(0,Math.min(w-1,cx+dx*f)),sy=Math.max(0,Math.min(h-1,cy+dy*f)),x0=Math.floor(sx),y0=Math.floor(sy),x1=Math.min(w-1,x0+1),y1=Math.min(h-1,y0+1),a=sx-x0,b=sy-y0,o=(y*w+x)*4;for(let c=0;c<3;c++)out.data[o+c]=source.data[(y0*w+x0)*4+c]*(1-a)*(1-b)+source.data[(y0*w+x1)*4+c]*a*(1-b)+source.data[(y1*w+x0)*4+c]*(1-a)*b+source.data[(y1*w+x1)*4+c]*a*b;out.data[o+3]=255}ctx.putImageData(out,0,0)}canvas.style.filter=state.compare?'none':colorFilter();}catch{toast('이미지를 표시하지 못했습니다. 다른 사진을 선택하세요.')}}
function editChange(key,value){state.undo.push({...state.edit});state.redo=[];state.edit[key]=value;render()}
function saveRecipes(){persist('b7c-recipes',state.recipes)}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function recipeDialog(id){const r=state.recipes.find(r=>r.id===id);if(!r)return;modal(esc(r.name),`<p>${esc(luts[r.edit.lut]?.[0]||'원본')} · 왜곡 ${r.edit.distortion||0}</p><p>이 브라우저에 저장한 웹 시안 레시피입니다.</p><div class="recipe-dialog-actions"><button class="studio-button" data-recipe-apply="${esc(id)}">사진에서 적용</button><button class="studio-button secondary" data-recipe-star="${esc(id)}">${r.favorite?'즐겨찾기 해제':'즐겨찾기'}</button><button class="studio-button secondary" data-recipe-share="${esc(id)}">웹 레시피 공유</button><button class="studio-button secondary" data-recipe-delete="${esc(id)}">삭제</button></div>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const ds=b.dataset;if(ds.screen){navigate(ds.screen);return}if(ds.theme){theme(ds.theme);return}if(ds.layout){state.layout=ds.layout;render();return}if(ds.mode){state.mode=ds.mode;render();return}if(ds.photo){if(state.selection){state.selected.has(ds.photo)?state.selected.delete(ds.photo):state.selected.add(ds.photo);render()}else{state.photoId=ds.photo;if(state.layout!=='wide')navigate('detail');else render()}return}if(ds.filter){state.filter=ds.filter;render();return}if(ds.tab){state.tab=ds.tab;render();return}if(ds.category){state.category=ds.category;toast(ds.category+' 카테고리 · 대표 LUT를 함께 표시합니다');render();return}if(ds.lut){editChange('lut',Number(ds.lut));return}if(ds.reset){editChange(ds.reset,defaults[ds.reset]);return}if(ds.recipe){recipeDialog(ds.recipe);return}for(const action of ['Apply','Star','Share','Delete']){const id=ds['recipe'+action];if(!id)continue;const r=state.recipes.find(r=>r.id===id);if(!r)return;if(action==='Apply'){state.edit={...defaults,...r.edit};$('#modal').close();navigate('editor')}if(action==='Star'){r.favorite=!r.favorite;saveRecipes();$('#modal').close();render()}if(action==='Share'){download(JSON.stringify({format:'beta7c-web-demo',name:r.name,edit:r.edit},null,2),'recipe-web-demo.json','application/json');toast('웹 시안 JSON · 앱 레시피 코드와 다릅니다.')}if(action==='Delete'){state.recipes=state.recipes.filter(x=>x!==r);saveRecipes();$('#modal').close();render()}return}const a=ds.action||ds.flow;if(!a)return;switch(a){case 'close':$('#modal').close();break;case 'edit':navigate('editor');break;case 'detail':navigate('detail');break;case 'photos':navigate('photos');break;case 'import':$('#photo-input').click();break;case 'select':state.selection=!state.selection;state.selected.clear();render();break;case 'apply-selection':if(!state.selected.size){toast('사진을 선택하세요.');break}state.photoId=[...state.selected][0];navigate('editor');toast('웹 시안에서는 선택한 첫 사진을 편집합니다.');break;case 'share-selection':toast(state.selected.size?`${state.selected.size}장 선택 · Android 공유 시트는 앱에서 제공됩니다.`:'사진을 선택하세요.');break;case 'share-photo':toast('원본 공유는 Android 앱에서 제공됩니다.');break;case 'compare':state.compare=!state.compare;render();break;case 'undo':if(state.undo.length){state.redo.push({...state.edit});state.edit=state.undo.pop();render()}break;case 'redo':if(state.redo.length){state.undo.push({...state.edit});state.edit=state.redo.pop();render()}break;case 'recipe-save':modal('레시피 저장','<p>색·왜곡 설정과 사진 커버를 이 브라우저에 보관합니다.</p><label for="recipe-name">레시피 이름</label><input id="recipe-name" maxlength="60" value="나의 필름 레시피">','<button class="studio-button secondary" data-action="close">취소</button><button class="studio-button" data-action="recipe-confirm">저장</button>');break;case 'recipe-confirm':{const name=$('#recipe-name').value.trim();if(!name){$('#recipe-name').focus();break}state.recipes.unshift({id:'recipe'+Date.now(),name,photo:photo().external?'demo0':photo().id,edit:{...state.edit}});saveRecipes();$('#modal').close();toast('레시피를 브라우저에 저장했습니다.');render();break}case 'photo-save':{if(state.screen!=='editor'){navigate('editor');break}await draw();const c=$('#photo-canvas'),out=document.createElement('canvas');out.width=c.width;out.height=c.height;const ctx=out.getContext('2d');ctx.filter=state.compare?'none':colorFilter();ctx.drawImage(c,0,0);out.toBlob(blob=>{if(blob){download(blob,'beta7c-web-preview.jpg','image/jpeg');toast('웹 미리보기 JPEG 저장 · Android 결과와 다릅니다.')}},'image/jpeg',.92);break}case 'connect':state.connected=true;render();toast('모의 연결입니다. USB에는 접근하지 않습니다.');break;case 'camera-import':navigate('photos');toast('데모 사진 목록을 열었습니다. 실제 가져오기는 앱에서 진행하세요.');break;case 'scan':toast('데모 새 사진 3장 · 실제 스캔 없음');break;case 'usb-help':modal('카메라 가져오기 설정','<ol><li>카메라 전원을 켭니다.</li><li>USB 연결 모드를 MTP로 설정합니다.</li><li>USB-C 케이블로 폰에 연결하고 앱에서 권한을 허용합니다.</li></ol><p>PC Remote 실험 진단은 별도 모드입니다. 여기서는 연결하지 않습니다.</p>');break;case 'diagnostic':case 'capture':modal(a==='capture'?'AF · 단발 촬영 실험':'PC Remote 실험 진단','<p>Android 앱의 별도 실험 기능입니다. 카메라 모드 변경 안내와 실행 확인 후 진행하는 흐름을 사용합니다.</p><p>이 웹 시안은 USB/PTP 명령을 전송하지 않습니다. 실기 검증은 별도입니다.</p>', '<button class="studio-button secondary" data-action="logs">웹 데모 로그 보기</button><button class="studio-button" data-action="close">닫기</button>');break;case 'logs':modal('웹 데모 로그','<pre>source=web-prototype\nusb_permission=not_requested\nptp_commands_sent=0\nhardware_verified=false</pre><p>실제 카메라 진단 로그가 아닙니다.</p>','<button class="studio-button secondary" data-action="log-download">데모 로그 저장</button><button class="studio-button" data-action="close">닫기</button>');break;case 'log-download':download('WEB DEMO ONLY\nUSB/PTP not executed\nhardware_verified=false\n','beta7c-web-demo.txt','text/plain');break;case 'recipe-import':modal('웹 레시피 가져오기','<p>이 사이트에서 내보낸 JSON을 붙여넣으세요. 앱의 레시피·QR 형식과는 다릅니다.</p><textarea id="recipe-json" rows="7" aria-label="웹 레시피 JSON"></textarea>','<button class="studio-button secondary" data-action="close">취소</button><button class="studio-button" data-action="recipe-import-confirm">가져오기</button>');break;case 'recipe-import-confirm':try{const r=JSON.parse($('#recipe-json').value);if(r.format!=='beta7c-web-demo'||typeof r.name!=='string'||!r.edit)throw Error();const ed={...defaults};for(const k of Object.keys(ed)){const v=r.edit[k];if(typeof v==='number'&&Number.isFinite(v))ed[k]=Math.max(k==='strength'||k==='lut'?0:-100,Math.min(k==='lut'?luts.length-1:100,k==='lut'?Math.round(v):v))}state.recipes.unshift({id:'recipe'+Date.now(),name:r.name.slice(0,60)||'가져온 레시피',photo:'demo0',edit:ed});saveRecipes();$('#modal').close();navigate('recipes');toast('웹 레시피를 가져왔습니다.')}catch{toast('유효한 웹 시안 레시피 JSON이 아닙니다.')}break;case 'notes':modal('화면 노트',`<p>${noteTexts[state.screen].join('</p><p>')}</p><p>${state.mode==='current'?'현재 구현을 소스로 재현한 화면입니다.':'개선 제안은 Android 앱에 적용되지 않았습니다.'}</p>`);break;case 'credits':modal('데모 사진 출처',`<p>사용자 사진이 아닌 Unsplash 데모 이미지입니다.</p><ul>${credits.map(c=>`<li><a href="${esc(c.source)}" target="_blank" rel="noopener">${esc(c.id)} · 원본 사진 ↗</a></li>`).join('')}</ul><p><a href="https://unsplash.com/license" target="_blank" rel="noopener">Unsplash License</a> · 앱 아이콘과 픽셀 아이콘은 프로젝트 소스를 사용했습니다.</p>`);break;case 'about':modal('β7C Screen Studio','<p>Android β7C 0.8.8 소스를 기준으로 만든 인터랙티브 웹 시안입니다. 실제 Android 화면 캡처가 아닙니다.</p><p>현재 구성과 개선 제안을 구분해 표시합니다. 4가지 앱 테마와 접힌 세로·펼친 세로·펼친 가로 배치를 비교할 수 있습니다.</p><p>사진은 공개 데모 이미지입니다. 외부 이미지는 브라우저에서만 처리하며 서버에 업로드하지 않습니다. 테마와 웹 레시피는 브라우저에 저장합니다.</p><p>USB/PTP·촬영·Android 공유 및 저장은 실행하지 않습니다. 웹 색상은 근사 표현이며 앱의 LUT 처리와 다릅니다. 왜곡은 동일 방식의 전체 사진 수동 조절을 웹에서 재현합니다.</p>');break}});
let sliderStart=null;document.addEventListener('pointerdown',e=>{if(e.target.matches('[data-range]'))sliderStart={...state.edit}});document.addEventListener('focusin',e=>{if(e.target.matches('[data-range]'))sliderStart={...state.edit}});document.addEventListener('input',e=>{const k=e.target.dataset.range;if(!k)return;state.edit[k]=Number(e.target.value);$('#value-'+k).textContent=state.edit[k];draw()});document.addEventListener('change',e=>{if(!e.target.dataset.range)return;if(sliderStart)state.undo.push(sliderStart);state.redo=[];sliderStart=null;render()});
$('#photo-input').addEventListener('change',e=>{let added=0;for(const f of [...e.target.files].slice(0,50)){if(!f.type.startsWith('image/')||f.size>64*1024*1024)continue;const p={id:'local'+Date.now()+added,url:URL.createObjectURL(f),name:f.name,external:true};photos.unshift(p);state.photoId=p.id;added++}e.target.value='';if(added){state.filter='외부';navigate('photos');toast(`${added}장 추가 · 브라우저에서만 사용합니다.`)}else toast('64MiB 이하의 지원 이미지를 선택하세요.')});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});new ResizeObserver(fit).observe($('.stage'));
Promise.all([fetch('assets/icons.json').then(r=>r.json()),fetch('assets/photo-credits.json').then(r=>r.json())]).then(([i,c])=>{icons=i;credits=c;render()}).catch(()=>{render();toast('일부 화면 자료를 불러오지 못했습니다.')});
